L.ACCOUNT_WIDE_ACHIEVEMENTS_TOOLTIP = "Достижения обычно отслеживаются на всю учётную запись, но есть некоторые эксклюзивные для определённых классов или рас достижения, которые Вы не сможете получить на основном персонаже."
