L.PVP_RANK_DESCRIPTION = "Hay un total de 14 rangos para ambas facciones. Cada rango requiere un mínimo de Puntos de Clasificación que se calcula semanalmente y se compara con otros jugadores de tu servidor. Cada rango otorga acceso a diferentes recompensas, desde consumibles JcJ hasta Monturas Épicas que no requieren la Habilidad de Montar Épica y piezas de equipo Épicas en los rangos más altos. Cada rango también se aplica a tu personaje como un Título."
