L.QUESTS_CHECKBOX_TOOLTIP = "Activa esta opción para rastrear misiones normales.\n\nPuedes hacer clic derecho en cualquier misión en las listas para abrir una ventana emergente con toda su cadena de misiones para ver tu progreso y si hay alguna misión requerida previa.\n\nNOTA: El rastreo de misiones Diarias, Semanales, Anuales y de mundo no se incluye en esta opción debido a los reinicios periódicos en la base de datos de Blizzard."
L.QUESTS_DESC = "Muestra todas las ID de misiones disponibles en el juego en orden numérico ascendente."
L.QUESTS_HIDDEN_TRACKER_CHECKBOX = "+DMO"
L.QUESTS_HIDDEN_TRACKER_CHECKBOX_TOOLTIP = "Activa esta opción para incluir específicamente el completado de Disparadores de misiones ocultas (DMO).\n\nDMO son los ID de Misiones invisibles para los jugadores, que se usan en segundo plano para supervisar el progreso o el estado del personaje/cuenta en diversas situaciones.\n\nProbablemente no te interese rastrearlas, ¿verdad? Seguro que no estás loco..."
L.QUESTS_LOCKED_CHECKBOX = "+Bloqueadas"
L.QUESTS_LOCKED_CHECKBOX_TOOLTIP = "Activa esta opción para incluir específicamente el rastreo de completado de misiones bloqueadas.\n\nLas misiones bloqueadas son aquellas que el personaje ya no puede completar (según los datos de ATT) jugando normalmente.\n\nLa obtención de estas misiones se basa mucho en la funcionalidad de Sincronización de Grupo o usando Misiones de cuenta para incorporar el progreso desde otros personajes."
