L.SHOW_ALL_LEARNABLE_QUEST_REWARDS_CHECKBOX_TOOLTIP = "Desactiva esta opción para esconder objetos marcados como \"No disponible en Botín Personal\" en misiones.\n\nEsto es útil para rastrear objetos que tu clase no puede usar de Botín de mundo, pero marcando las misiones como completadas.\n\nAlgunos objetos pueden marcarse incorrectamente: este ajuste ESCONDERÁ objetos que puedes obtener!"
L.SHOW_ALL_SEASONAL = "Todos los eventos de temporales"
L.SHOW_ALL_SEASONAL_TOOLTIP = "Activa este ajuste si quieres ver todos los eventos temporales, en vez de sólo los eventos temporales activos.\n\nNOTA: Los eventos temporales se van a mostrar como activos automáticamente 7 días antes del inicio."
L.SHOW_BOE_CHECKBOX = "Objetos BoE/BoA"
L.SHOW_BOE_CHECKBOX_TOOLTIP = "Activa este ajuste si quieres ver los objetos Se liga al equipar/Cuenta.\n\nDesactivar este ajuste puede ser útil cuando quieres acabar una Mazmorra clásica con un personaje y no quieres conseguir específicamente esos objetos que pueden ser conseguidos con un personaje secundario o en la Casa de Subastas.\n\nPE: No pierdas la cabeza intentando conseguir el Péndulo de Fatalidad."
L.SHOW_COLLECTED_THINGS_CHECKBOX = "Muestra las cosas coleccionadas"
L.SHOW_COLLECTED_THINGS_CHECKBOX_TOOLTIP = "Activa esta opción para ver las cosas que ya has coleccionado.\n\nRecomendamos que desactives este ajuste para conservar espacio en la Mini Lista y te permite ver rápidamente qué te falta de la zona."
L.SHOW_COLLECTION_PROGRESS_CHECKBOX = "Progreso de colección"
L.SHOW_COLLECTION_PROGRESS_CHECKBOX_TOOLTIP = "Activa esta opción si quieres ver tu progreso para coleccionar una cosa o completar un grupo de cosas en la esquina superior derecha de la ventana emergente.\n\nRecomendamos que mantengas este ajuste activo."
L.SHOW_COMPLETED_GROUPS_CHECKBOX = "Muestra los grupos completados"
L.SHOW_COMPLETED_GROUPS_CHECKBOX_TOOLTIP = "Activa esta opción si quieres ver los grupos completados como cabecera con un porcentaje de completado. Si un grupo no tiene nada relevante para tu clase, este ajuste hará que también se muestren estos grupos en el listado.\n\nRecomendamos que desactives este ajuste para conservar espacio en la Mini Lista y te permite ver rápidamente qué te falta de la zona."
L.SHOW_CRAFTED_ITEMS_CHECKBOX = "Mostrar objetos fabricados"
L.SHOW_CRAFTED_ITEMS_CHECKBOX_TOOLTIP = "Activa esta opción si quieres ver la lista de todos los objetos que se pueden fabricar por cualquiera de tus personajes para un ingrediente en su ventana emergente."
L.SHOW_CURRENCY_CALCULATIONS_CHECKBOX = "Cálculo de divisas"
L.SHOW_CURRENCY_CALCULATIONS_CHECKBOX_TOOLTIP = "Activa esta opción para mostrar el numero aproximado de Objetos/Divisas requeridas para coleccionar cosas.\n\nPara contenedores que no dan todas sus recompensas a la vez, el aproximado puede ser menor al requerido realmente."
L.SHOW_ICON_PORTRAIT_CHECKBOX = "Iconos de Retratos"
L.SHOW_ICON_PORTRAIT_CHECKBOX_TOOLTIP = "Activa esta opción si quieres ver el icono de la criatura en vez de los iconos por defecto del tipo de objeto.\n\nPE: Cuando estas mirando jefes de banda, esta opción de va a mostrar la cara del jefe de banda en vez del icono de dificultad.\n\nPor defecto: Activado"
L.SHOW_ICON_PORTRAIT_FOR_QUESTS_CHECKBOX = "Para misiones"
