L.SHOW_INCOMPLETE_THINGS_CHECKBOX = "Muestra todas las cosas repetibles/rastreables"
L.SHOW_INCOMPLETE_THINGS_CHECKBOX_TOOLTIP = "Activa esta opción si quieres ver los objetos, PNJs y cabeceras que se pueden rastrear en el juego sin que se consideren 'coleccionables' necesariamente.\n\nPuedes usarlo para ayudarte a conseguir el logro Maestro cultural si aún no lo tienes.\n\nNOTA: Los enemigos Raros y las aventuras también aparecerán en el listado con este ajuste activado."
L.SHOW_MODELS_CHECKBOX = "Previsualizar Modelos"
